python3 -c "
import sys; sys.path.insert(0, r'E:\project\AIc\ship-sentinel\backend')
from xlsx_reader import read_rows, read_records
path = r'E:\project\AIc\商品资料_1784528031175.xlsx'
# Get raw rows
rows = read_rows(path)
print(f'Rows: {len(rows)}, Header cols: {len(rows[0])}')
# Write header and samples to file for proper encoding
with open('_col_dump.txt', 'w', encoding='utf-8') as f:
    for i, h in enumerate(rows[0]):
        f.write(f'col[{i}] = {repr(h)}\n')
    f.write(f'\nTotal rows: {len(rows)-1}\n')
    f.write('\n=== ROW 1 (first data) ===\n')
    for i, v in enumerate(rows[1]):
        if v is not None:
            f.write(f'col[{i}] = {repr(v)}\n')
    f.write('\n=== ROW 2 ===\n')
    for i, v in enumerate(rows[2]):
        if v is not None:
            f.write(f'col[{i}] = {repr(v)}\n')
    f.write('\n=== LAST ROW ===\n')
    for i, v in enumerate(rows[-1]):
        if v is not None:
            f.write(f'col[{i}] = {repr(v)}\n')
print('done')
